260	static int bk7258_start_next_locked(FAR struct bk7258_audio_s *priv)
261	{
262	  FAR struct ap_buffer_s *apb;
263	  struct bk7258_dma_m2p_cfg_s cfg;
264	  int ret;
265	
266	  if (priv->closing || priv->stopping || priv->faulted ||
267	      priv->fault_pending || !priv->dac_running || priv->dma_active)
268	    {
269	      return OK;
270	    }
271	
272	  apb = (FAR struct ap_buffer_s *)dq_peek(&priv->pendq);
273	  if (apb == NULL)
274	    {
275	      return OK;
276	    }
277	
278	  cfg.buf          = (uintptr_t)apb->samp;
279	  cfg.buf_len      = apb->nbytes;
280	  cfg.dest         = bk7258_dac_fifo_addr();
281	  cfg.dest_req_mux = BK7258_DMA_REQ_AUDIO_DAC;
282	  /* The DAC FIFO port is a single 32-bit register (AUD_DAC_FPORT).  Each
283	   * word is one stereo frame {R:16, L:16} or two mono samples.  Both
284	   * source and destination widths must be 32-bit so the DMA engine drops
285	   * exactly one word into the FIFO per transfer beat.  Using 16-bit width
286	   * would leave the FIFO half-loaded and the "finish" interrupt would
287	   * never fire.
288	   */
289	
290	  cfg.src_width    = BK7258_DMA_WIDTH_32;
291	  cfg.dst_width    = BK7258_DMA_WIDTH_32;
292	  /* AVDK's reference audio path uses REPEAT + src loop instead of a
293	   * one-shot transfer.  Empirical trace with one_shot=true showed the DMA
294	   * moves only 3 words then stalls (remain_len frozen).  In REPEAT mode
295	   * the engine keeps consuming DREQ pulses from the DAC FIFO until
296	   * transfer_len is reached, which matches the peripheral request timing
297	   * BK7258's audio block appears to expect.
298	   */
299	
300	  cfg.one_shot     = false;
301	  cfg.callback     = bk7258_audio_dma_cb;
302	  cfg.arg          = priv;
303	
304	  /* Clean the source buffer out of D-cache; GDMA reads from RAM. */
305	
306	  up_clean_dcache((uintptr_t)apb->samp,
307	                  (uintptr_t)apb->samp + apb->nbytes);
308	
309	  ret = bk7258_gdma_start_m2p(priv->dma_ch, &cfg);
310	  if (ret < 0)
311	    {
312	      AUD_ERR("gdma_start_m2p failed: %d", ret);
313	      return ret;
314	    }
315	
316	  priv->dma_active = true;
317	  return OK;
318	}
