476	/* DMA IRQ callback.  IRQ completion and enqueue are the only queue
477	 * advancers.  Faults only close the run gate and defer all sleeping, PA,
478	 * hardware-stop and upper-half work to LPWORK.
479	 */
480	
481	void bk7258_audio_dma_cb(int ch, uint32_t event, FAR void *arg)
482	{
483	  FAR struct bk7258_audio_s *priv = arg;
484	  FAR struct ap_buffer_s *apb;
485	  irqstate_t flags;
486	  bool need_worker = false;
487	  int ret;
488	
489	  (void)ch;
490	
491	  flags = spin_lock_irqsave(&priv->lock);
492	
493	  if ((event & BK7258_DMA_EVENT_BUS_ERROR) != 0u)
494	    {
495	      if (priv->dac_running || priv->dma_active)
496	        {
497	          AUD_ERR("DMA bus error");
498	          bk7258_fault_locked(priv, -EIO, false);
499	          need_worker = true;
500	        }
501	    }
502	  else if ((event & BK7258_DMA_EVENT_FULL) != 0u && priv->dma_active)
503	    {
504	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
505	      priv->dma_active = false;
506	      if (apb != NULL)
507	        {
508	          dq_addlast(&apb->dq_entry, &priv->doneq);
509	          need_worker = true;
510	        }
511	
512	      if (priv->dac_running && !priv->closing && !priv->stopping &&
513	          !priv->faulted)
514	        {
515	          ret = bk7258_start_next_locked(priv);
516	          if (ret < 0)
517	            {
518	              bk7258_fault_locked(priv, ret, false);
519	              need_worker = true;
520	            }
521	          else if (!priv->dma_active)
522	            {
523	              if (priv->final_seen)
524	                {
525	                  priv->complete_pending = true;
526	                }
527	              else
528	                {
529	                  priv->underrun_pending = true;
530	                }
531	
532	              need_worker = true;
533	            }
534	        }
535	    }
536	
537	  if (need_worker)
538	    {
539	      bk7258_schedule_worker_locked(priv);
540	    }
541	
542	  spin_unlock_irqrestore(&priv->lock, flags);
543	}
