407	#ifdef CONFIG_AUDIO_BK7258
408	  /* Decisive audio-bus probe.  The -F trace already showed that 32 CPU
409	   * writes to DAC_FPORT leave FIFO_STATUS unchanged (EMPTY bits stay 1).
410	   * This probe isolates WHY by testing three independent questions with
411	   * bare volatile pointers (same style as the RAW ana-reg probe below, so
412	   * it needs no extra includes):
413	   *
414	   *  (A) Does a write to a readable audio register commit?  We write a
415	   *      magic value into DAC_CONFIG0 (0x4780001c, R/W, readback-able) and
416	   *      read it back.  Readback == magic => the AP CPU CAN commit writes
417	   *      to the audio register bank, so the FPORT failure is specific to
418	   *      the FIFO data port, not a global bus/clock/secure gate.
419	   *
420	   *  (B) Do ANY of the four FIFO ports accept data?  We push one word to
421	   *      DTMF/ADC/DAC/DMIC FPORT in turn and read FIFO_STATUS after each.
422	   *      FIFO_STATUS has separate EMPTY bits per FIFO (DTMF=15, ADCL=14,
423	   *      DACR=12, DACL=13, DMIC=23).  If the matching EMPTY bit clears for
424	   *      any port, that FIFO is alive; if NONE clears, the whole FIFO
425	   *      write path is dead (clock/gate/reset at the FIFO subsystem level).
426	   *
427	   *  (C) Does DAC_ENABLE gate the FPORT write?  We write DAC_FPORT with
428	   *      DAC_ENABLE=1, record status, then clear DAC_ENABLE and write
429	   *      again.  If status is identical either way, ENABLE does not gate
430	   *      the FIFO input — pointing at the FIFO subsystem, not the DAC.
431	   */
432	  if (g_trace_mode || g_fifo_cpu_mode)
433	    {
434	      volatile uint32_t *p_audio_cfg  = (volatile uint32_t *)0x478000c0u;
435	      volatile uint32_t *p_dac_cfg0    = (volatile uint32_t *)0x4780001cu;
436	      volatile uint32_t *p_fifo_status = (volatile uint32_t *)0x47800038u;
437	      volatile uint32_t *p_dtmf_fport  = (volatile uint32_t *)0x47800040u;
438	      volatile uint32_t *p_adc_fport   = (volatile uint32_t *)0x47800044u;
439	      volatile uint32_t *p_dac_fport   = (volatile uint32_t *)0x47800048u;
440	      volatile uint32_t *p_dmic_fport  = (volatile uint32_t *)0x4780004cu;
441	      struct bk7258_dac_stats_s ps;
442	      /* bit30-31 of DAC_CONFIG0 are RESERVED (hardware forces them to 0), so
443	       * the magic stays within bit0-29 to make readback == magic meaningful.
444	       * An impossible HPF2 coef + gain + notchen pattern that the running
445	       * config would never have. */
446	      uint32_t magic = UINT32_C(0x1A3C6901);
447	      uint32_t cfg0_orig;
448	      uint32_t cfg0_rb;
449	      uint32_t ac_orig;
450	      uint32_t fs_pre;
451	      uint32_t fs_dtmf;
452	      uint32_t fs_adc;
453	      uint32_t fs_dac_en1;
454	      uint32_t fs_dac_en0;
455	      uint32_t ac_after;
456	
457	      bk7258_dac_get_stats(&ps);
458	      printf("[bk] FPORT-KICK pre  audio=%08lx fifo_cfg=%08lx fifo_st=%08lx "
459	             "dac_cfg0=%08lx clk=%08lx ext=%08lx\n",
460	             (unsigned long)ps.audio_config, (unsigned long)ps.fifo_config,
461	             (unsigned long)ps.fifo_status, (unsigned long)ps.dac_config0,
462	             (unsigned long)ps.clk_control, (unsigned long)ps.extend_cfg);
463	
464	      /* Dump the analog-side audio enable state.  AVDK's CP
465	       * sys_hal_power_config_default() clears ana_reg25.audioen (bit31)
466	       * and test_ckaudio_en (bit20) at boot; the audio driver's PM vote
467	       * is what puts them back.  ana_reg25 is also the APLL config reg,
468	       * so BK7258_APLL_CONFIG_VAL 0xC2A0AE86 carries audioen=1 as a
469	       * side effect of APLL programming — but only if the SPI trigger
470	       * pulse actually loaded it.  reg5 bit13 = PWDAUDPLL (0=powered).
471	       * reg23 bit31 = a second audioen field.  Read all three raw.
472	       */
473	        {
474	          volatile uint32_t *p5   = (volatile uint32_t *)0x44010114u;
475	          volatile uint32_t *p23  = (volatile uint32_t *)0x4401015cu;
476	          volatile uint32_t *p25  = (volatile uint32_t *)0x44010164u;
477	          volatile uint32_t *pspi = (volatile uint32_t *)0x440100e8u;
478	          uint32_t v5  = *p5;
479	          uint32_t v23 = *p23;
480	          uint32_t v25 = *p25;
481	          printf("[bk] FPORT-KICK ana  r5=%08lx(apll_pwr=%lu) "
482	                 "r23=%08lx(aud_en=%lu) r25=%08lx(aud_en=%lu "
483	                 "spi_trig=%lu ckaudio=%lu) spi_state=%08lx\n",
484	                 (unsigned long)v5,  (unsigned long)((v5 >> 13) & 1),
485	                 (unsigned long)v23, (unsigned long)((v23 >> 31) & 1),
486	                 (unsigned long)v25, (unsigned long)((v25 >> 31) & 1),
487	                 (unsigned long)((v25 >> 18) & 1),
488	                 (unsigned long)((v25 >> 20) & 1),
489	                 (unsigned long)*pspi);
490	        }
491	
492	      /* (A) write/read DAC_CONFIG0 — is the audio write bus alive? */
493	      cfg0_orig = *p_dac_cfg0;
494	      *p_dac_cfg0 = magic;
495	      up_udelay(2);
496	      cfg0_rb = *p_dac_cfg0;
497	      *p_dac_cfg0 = cfg0_orig;           /* restore */
498	      up_udelay(2);
499	      printf("[bk] FPORT-KICK (A) DAC_CFG0 wr=%08lx rd=%08lx orig=%08lx "
500	             "%s\n",
501	             (unsigned long)magic, (unsigned long)cfg0_rb,
502	             (unsigned long)cfg0_orig,
503	             (cfg0_rb == magic) ? "WRITEBUS_OK" : "WRITEBUS_DEAD");
504	
505	      /* (B) push one word to each FPORT, read FIFO_STATUS after each.
506	       *     EMPTY bits: DTMF=15 ADCL=14 DACL=13 DACR=12 DMIC=23. */
507	      fs_pre = *p_fifo_status;
