492	      /* (A) write/read DAC_CONFIG0 — is the audio write bus alive? */
493	      cfg0_orig = *p_dac_cfg0;
494	      *p_dac_cfg0 = magic;
495	      up_udelay(2);
496	      cfg0_rb = *p_dac_cfg0;
497	      *p_dac_cfg0 = cfg0_orig;           /* restore */
498	      up_udelay(2);
499	      printf("[bk] FPORT-KICK (A) DAC_CFG0 wr=%08lx rd=%08lx orig=%08lx "
500	             "%s\n",
501	             (unsigned long)magic, (unsigned long)cfg0_rb,
502	             (unsigned long)cfg0_orig,
503	             (cfg0_rb == magic) ? "WRITEBUS_OK" : "WRITEBUS_DEAD");
504	
505	      /* (B) push one word to each FPORT, read FIFO_STATUS after each.
506	       *     EMPTY bits: DTMF=15 ADCL=14 DACL=13 DACR=12 DMIC=23. */
507	      fs_pre = *p_fifo_status;
508	      *p_dtmf_fport = UINT32_C(0x00010001);
509	      up_udelay(2);
510	      fs_dtmf = *p_fifo_status;
511	      *p_adc_fport  = UINT32_C(0x00010001);
512	      up_udelay(2);
513	      fs_adc = *p_fifo_status;
514	      *p_dac_fport  = UINT32_C(0x00010001);
515	      up_udelay(2);
516	      fs_dac_en1 = *p_fifo_status;
517	      printf("[bk] FPORT-KICK (B) fifo_st pre=%08lx dtmf=%08lx adc=%08lx "
518	             "dac=%08lx\n", (unsigned long)fs_pre, (unsigned long)fs_dtmf,
519	             (unsigned long)fs_adc, (unsigned long)fs_dac_en1);
520	      printf("[bk] FPORT-KICK (B) dtmf_empty_chg=%lu adcl_empty_chg=%lu "
521	             "dacl_empty_chg=%lu dacr_empty_chg=%lu dmic_empty_chg=%lu\n",
522	             (unsigned long)(((fs_pre ^ fs_dtmf) >> 15) & 1),
523	             (unsigned long)(((fs_pre ^ fs_dtmf) >> 14) & 1),
524	             (unsigned long)(((fs_pre ^ fs_dac_en1) >> 13) & 1),
525	             (unsigned long)(((fs_pre ^ fs_dac_en1) >> 12) & 1),
526	             (unsigned long)0);
527	
528	      /* (C) does DAC_ENABLE gate the FPORT?  Clear ENABLE, write, status. */
529	      ac_orig = *p_audio_cfg;
530	      *p_audio_cfg = ac_orig & ~UINT32_C(0x4);   /* clear DAC_ENABLE bit2 */
531	      up_udelay(2);
532	      *p_dac_fport  = UINT32_C(0x00010001);
533	      up_udelay(2);
534	      fs_dac_en0 = *p_fifo_status;
535	      *p_audio_cfg = ac_orig;                    /* restore ENABLE */
536	      up_udelay(2);
537	      ac_after = *p_audio_cfg;
538	      printf("[bk] FPORT-KICK (C) dac_en1_st=%08lx dac_en0_st=%08lx "
539	             "(same=%d) audio_orig=%08lx restored=%08lx\n",
540	             (unsigned long)fs_dac_en1, (unsigned long)fs_dac_en0,
541	             (int)(fs_dac_en1 == fs_dac_en0),
542	             (unsigned long)ac_orig, (unsigned long)ac_after);
543	
544	      /* 10x rapid DAC FPORT writes with per-write status sample — catches
545	       * a momentarily-cleared EMPTY if the DAC drains within microseconds. */
546	      for (int k = 0; k < 10; k++)
547	        {
548	          uint32_t s0 = *p_fifo_status;
549	          *p_dac_fport = UINT32_C(0x00010001);
550	          uint32_t s1 = *p_fifo_status;
551	          printf("[bk] FPORT-KICK  wr%-2d st_before=%08lx st_after=%08lx "
552	                 "(L_empty=%lu R_empty=%lu)\n",
553	                 k, (unsigned long)s0, (unsigned long)s1,
554	                 (unsigned long)((s1 >> 13) & 1),
555	                 (unsigned long)((s1 >> 12) & 1));
556	          usleep(1);
557	        }
558	      fflush(stdout);
559	    }
560	
561	  if (g_trace_mode)
562	    {
563	      /* Sample the DMA + audio-block state every 5 ms, 40 times.  This
564	       * tells us whether:
565	       *  - remain_len is truly frozen or slowly decrementing
566	       *  - fifo_status oscillates (DAC drains + DMA refills) or is static
567	       *  - the GDMA ISR ever fires (isr_count > 0)
568	       */
569	
570	      struct bk7258_gdma_stats_s gs;
571	      struct bk7258_dac_stats_s  ds;
572	
573	      /* RAW analog-register write/read probe — bypasses every helper in
574	       * bk7258_dac.c so we can decide, independent of the DAC HAL, whether
575	       * the AP CPU can write the analog register file at all.  We pick a
576	       * magic value that cannot appear by chance, write it to ana_reg20
577	       * (the DAC analog config), and read it back.  Readback == magic means
578	       * analog writes work and the DAC HAL's address math is the only
579	       * suspect; readback == 0 or stale means the AP cannot commit analog
580	       * writes (power/clock/secure gating on this core).
581	       */
582	
583	      {
584	        /* Raw analog-reg probe.  Addresses (ana_reg0 base = 0x44010100):
585	         *   ana_reg5  (APLL power, bit13=pwdaudpll) = 0x44010114
586	         *   ana_reg25 (APLL config)                 = 0x44010164
587	         *   ana_reg26 (APLL cal)                     = 0x44010168
588	         *   SPI state                                = 0x440100e8
589	         * Hard-coded to avoid pulling bk7258_internal.h into user space.
590	         *
591	         * This test: (1) confirm analog writes commit (write magic to
592	         * reg25, read back).  (2) the real question — does clearing reg5
593	         * bit13 (power UP the APLL) stick?  bk7258_apll_program does this
594	         * via a RMW but the -F trace shows reg5 bit13 still =1 after the
595	         * APLL phase, so the DAC has no clock and DREQ never asserts.
596	         */
597	        volatile uint32_t *p5   = (volatile uint32_t *)0x44010114u;
598	        volatile uint32_t *p25  = (volatile uint32_t *)0x44010164u;
599	        volatile uint32_t *p26  = (volatile uint32_t *)0x44010168u;
600	        volatile uint32_t *spi  = (volatile uint32_t *)0x440100e8u;
601	        uint32_t r5b  = *p5;
602	        uint32_t r25b = *p25;
603	        uint32_t magic = UINT32_C(0xDEADBEEF);
604	        uint32_t r5_after_clr;
605	        uint32_t r25_rd;
606	
607	        /* (1) plain write to reg25, read back, then RESTORE so the
608	         * APLL config + audioen bits survive the rest of the trace.
609	         * The earlier build left reg25=DEADBEEF, which clobbered the
610	         * APLL config and made the 40-sample trace run with a broken
611	         * APLL. */
612	        *p25 = magic;
613	        up_udelay(50);
614	        r25_rd = *p25;
615	        *p25 = r25b;                      /* restore APLL config + audioen */
616	        up_udelay(50);
617	
618	        /* (2) RMW reg5 bit13 -> 0 (power up APLL) */
619	        *p5 = r5b & ~(UINT32_C(1) << 13);
620	        up_udelay(50);
621	        r5_after_clr = *p5;
622	
623	        printf("[bk] PROBE r5 before=%08lx clr13->%08lx (bit13=%lu) "
624	               "r25 wr=%08lx rd=%08lx r25_orig=%08lx restored=%08lx "
625	               "spi=%08lx r26=%08lx\n",
626	               (unsigned long)r5b, (unsigned long)r5_after_clr,
627	               (unsigned long)((r5_after_clr >> 13) & 1),
628	               (unsigned long)magic, (unsigned long)r25_rd,
629	               (unsigned long)r25b, (unsigned long)*p25,
630	               (unsigned long)*spi, (unsigned long)*p26);
631	        fflush(stdout);
632	      }
633	
634	      bk7258_gdma_get_stats(&gs);
635	      printf("[bk] TRACE cfg req=%08lx src_loop=%08lx-%08lx\n",
636	             (unsigned long)gs.ch[0].reqmux,
637	             (unsigned long)gs.ch[0].src_loop_start,
638	             (unsigned long)gs.ch[0].src_loop_end);
639	      printf("[bk] TRACE cfg dst_loop=%08lx-%08lx\n",
640	             (unsigned long)gs.ch[0].dst_loop_start,
641	             (unsigned long)gs.ch[0].dst_loop_end);
642	      printf("[bk] TRACE t(ms) remain st     src_rd dst_wr ctrl prio\n");
643	      printf("[bk] TRACE       fifo_st fifo_cfg audio_cfg ist0 ist_alc isr fin err\n");
644	      for (int t = 0; t < 40; t++)
645	        {
646	          bk7258_gdma_get_stats(&gs);
647	          bk7258_dac_get_stats(&ds);
648	          uint32_t remain = gs.ch[0].status & 0x1FFFFu;
649	          printf("  %3d %5lu %08lx %08lx %08lx %08lx %08lx\n",
650	                 t * 5,
651	                 (unsigned long)remain,
652	                 (unsigned long)gs.ch[0].status,
653	                 (unsigned long)gs.ch[0].src,
654	                 (unsigned long)gs.ch[0].dst,
655	                 (unsigned long)gs.ch[0].ctrl,
656	                 (unsigned long)gs.prio_mode);
657	          printf("      %08lx %08lx %08lx %08lx %08lx %3lu %3lu %3lu\n",
658	                 (unsigned long)ds.fifo_status,
659	                 (unsigned long)ds.fifo_config,
660	                 (unsigned long)ds.audio_config,
661	                 (unsigned long)gs.int_status0,
662	                 (unsigned long)gs.int_allocate,
663	                 (unsigned long)gs.isr_count,
664	                 (unsigned long)gs.finish_count,
665	                 (unsigned long)gs.buserr_count);
666	          fflush(stdout);
667	          usleep(5000);
668	        }
669	
670	      (void)ioctl(fd, AUDIOIOC_STOP, 0);
671	      goto cleanup;
672	    }
673	#endif
674	
675	  /* Drive the queue until COMPLETE. */
676	
677	  bool done = false;
678	  int timeout_count = 0;
679	  while (!done)
680	    {
681	      struct timespec abs_to;
682	      clock_gettime(CLOCK_REALTIME, &abs_to);
683	      abs_to.tv_sec += 2;
684	      msglen = mq_timedreceive(mq, (FAR char *)&msg, sizeof(msg), &prio,
685	                               &abs_to);
686	      if (msglen < 0 && errno == ETIMEDOUT)
687	        {
688	          timeout_count++;
689	          fprintf(stderr, "[bk] timeout %d, dumping GDMA state\n",
690	                  timeout_count);
691	#ifdef CONFIG_AUDIO_BK7258
692	          {
693	            struct bk7258_gdma_stats_s st;
694	            bk7258_gdma_get_stats(&st);
695	            printf("  isr=%lu fin=%lu half=%lu err=%lu\n",
696	                   (unsigned long)st.isr_count,
697	                   (unsigned long)st.finish_count,
698	                   (unsigned long)st.half_count,
699	                   (unsigned long)st.buserr_count);
700	            printf("  cpu_int_en @0x%08lx = 0x%08lx (bit11 must be 1)\n",
701	                   (unsigned long)st.cpu_int_en_reg,
702	                   (unsigned long)st.cpu_int_en_val);
703	            printf("  dev_clk_en = 0x%08lx (bit16 must be 1)\n",
704	                   (unsigned long)st.dev_clk_en_val);
705	            printf("  prio_mode=0x%08lx int_st0=0x%08lx int_alloc=0x%08lx\n",
706	                   (unsigned long)st.prio_mode,
707	                   (unsigned long)st.int_status0,
708	                   (unsigned long)st.int_allocate);
709	            for (int ci = 0; ci < 8; ci++)
710	              {
711	                if (st.ch[ci].ctrl == 0 && !st.ch[ci].in_use)
712	                  {
713	                    continue;
714	                  }
715	                printf("  ch%d: ctrl=%08lx st=%08lx src=%08lx dst=%08lx "
716	                       "req=%08lx use=%u\n", ci,
717	                       (unsigned long)st.ch[ci].ctrl,
718	                       (unsigned long)st.ch[ci].status,
719	                       (unsigned long)st.ch[ci].src,
720	                       (unsigned long)st.ch[ci].dst,
721	                       (unsigned long)st.ch[ci].reqmux,
722	                       (unsigned)st.ch[ci].in_use);
723	              }
724	
725	            struct bk7258_dac_stats_s ds;
726	            bk7258_dac_get_stats(&ds);
727	            printf("  DAC: audio_cfg=%08lx fifo_cfg=%08lx fifo_st=%08lx\n",
728	                   (unsigned long)ds.audio_config,
729	                   (unsigned long)ds.fifo_config,
730	                   (unsigned long)ds.fifo_status);
731	            printf("       dac_cfg0=%08lx extend=%08lx clk_ctrl=%08lx\n",
732	                   (unsigned long)ds.dac_config0,
733	                   (unsigned long)ds.extend_cfg,
734	                   (unsigned long)ds.clk_control);
735	          }
736	#endif
737	          if (timeout_count >= 3)
738	            {
739	              fprintf(stderr, "[bk] giving up\n");
740	              break;
741	            }
742	          continue;
743	        }
744	
745	      if (msglen < (ssize_t)sizeof(msg))
746	        {
747	          fprintf(stderr, "mq_receive failed: %d\n", errno);
748	          break;
749	        }
750	
751	      switch (msg.msg_id)
752	        {
753	          case AUDIO_MSG_DEQUEUE:
754	            printf("[bk] deq\n"); fflush(stdout);
755	            apb = (FAR struct ap_buffer_s *)msg.u.ptr;
756	
757	            if (bytes_written < total_bytes)
758	              {
759	                size_t chunk = buf_info.buffer_size;
760	                if (bytes_written + chunk >= total_bytes)
761	                  {
762	                    chunk = total_bytes - bytes_written;
763	                    apb->flags |= AUDIO_APB_FINAL;
764	                  }
765	
766	                fill_sine((FAR int16_t *)apb->samp, chunk / 2, &phase);
767	                apb->nbytes  = chunk;
768	                apb->curbyte = 0;
769	                bytes_written += chunk;
770	
771	                buf_desc.u.buffer = apb;
772	                (void)ioctl(fd, AUDIOIOC_ENQUEUEBUFFER,
773	                            (unsigned long)&buf_desc);
774	              }
775	            else
776	              {
777	                buf_desc.u.buffer = apb;
778	                (void)ioctl(fd, AUDIOIOC_FREEBUFFER,
779	                            (unsigned long)&buf_desc);
780	              }
781	            break;
782	
783	          case AUDIO_MSG_COMPLETE:
784	            printf("[bk] complete\n"); fflush(stdout);
785	            done = true;
786	            break;
787	
788	          case AUDIO_MSG_UNDERRUN:
789	            fprintf(stderr, "underrun\n");
790	            break;
791	
792	          case AUDIO_MSG_IOERR:
793	            fprintf(stderr, "io error\n");
794	            done = true;
795	            break;
796	
797	          default:
798	            printf("[bk] msg id=%u\n", msg.msg_id); fflush(stdout);
799	            break;
800	        }
801	    }
802	
803	  (void)ioctl(fd, AUDIOIOC_STOP, 0);
804	  printf("[bk] stop ok\n"); fflush(stdout);
805	
806	cleanup:
807	  (void)ioctl(fd, AUDIOIOC_UNREGISTERMQ, (unsigned long)mq);
808	  (void)ioctl(fd, AUDIOIOC_RELEASE, 0);
809	  mq_close(mq);
810	  mq_unlink(MQ_NAME);
811	  close(fd);
812	  return (ret < 0) ? EXIT_FAILURE : EXIT_SUCCESS;
813	}
