393		sys_drv_analog_reg13_set(0x0F808400);
394		sys_drv_analog_reg14_set(0x40038002);    //gain :15
395		sys_drv_analog_reg15_set(0x40038002);
396		//sys_drv_analog_reg16_set(0x89C02401);
397		sys_drv_analog_reg16_set(0x89C62401);
398		sys_drv_analog_reg17_set(0x80100000);
399	
400		//enable audvdd 1.0v and 1.5v
401		sys_drv_aud_vdd1v_en(1);
402		sys_drv_aud_vdd1v5_en(1);
403	#endif
