409	bk_err_t bk_aud_driver_deinit(void)
410	{
411		if (!s_aud_driver_is_init) {
412			return BK_OK;
413		}
414	
415		/* check module init status */
416		if (s_aud_module_init_sta.adc_is_init || s_aud_module_init_sta.dmic_is_init || s_aud_module_init_sta.dtmf_is_init || s_aud_module_init_sta.dac_is_init) {
417			return BK_OK;
418		}
419	
420		//reset audo configure
421	#if CONFIG_AUDIO_ADC
422		bk_aud_adc_deinit();
423	#endif
424	#if CONFIG_AUDIO_DAC
425		bk_aud_dac_deinit();
426	#endif
427	#if CONFIG_AUDIO_DTMF
428		bk_aud_dtmf_deinit();
429	#endif
430	#if CONFIG_AUDIO_DMIC
431		bk_aud_dmic_deinit();
432	#endif
433	
434		//disable audio interrupt
435		sys_drv_aud_int_en(0);
436		//ungister isr
437		bk_int_isr_unregister(INT_SRC_AUDIO);
438	
439		// config analog register
440		sys_hal_aud_clock_en(0);
441	
442	#if CONFIG_SOC_BK7236XX
443		sys_hal_set_ana_reg18_value(0);
444		sys_hal_set_ana_reg19_value(0);
445		sys_hal_set_ana_reg20_value(0);
446		sys_hal_set_ana_reg21_value(0);
447	
448		sys_drv_aud_audbias_en(0);
449	    aud_hal_set_clk_control_soft_reset(0);
450		aud_hal_set_clk_control_soft_reset(1);
451	    aud_hal_set_clk_control_soft_reset(0);
452	#endif
453	
454	#if CONFIG_SOC_BK7256XX
455		//disable audvdd 1.0v and 1.5v
456		sys_drv_aud_vdd1v_en(0);
457		sys_drv_aud_vdd1v5_en(0);
458	
459		// config analog register
460		sys_drv_analog_reg12_set(0x0);
461		sys_drv_analog_reg13_set(0x0);
462		sys_drv_analog_reg14_set(0x0);
463		sys_drv_analog_reg15_set(0x0);
464		sys_drv_analog_reg16_set(0x0);
465		sys_drv_analog_reg17_set(0x0);
466	
467		//disable audpll en
468		sys_drv_aud_audpll_en(0);
469	#endif
470	
471		bk_pm_clock_ctrl(PM_CLK_ID_AUDIO, CLK_PWR_CTRL_PWR_DOWN);
472		bk_pm_module_vote_power_ctrl(PM_POWER_SUB_MODULE_NAME_AUDP_AUDIO, PM_POWER_MODULE_STATE_OFF);
473	
474		s_aud_driver_is_init = false;
475	
476		return BK_OK;
477	}
