79	/* Fill an S16_LE buffer with a bounded sine wave at g_freq_hz.  phase is
80	 * carried across buffers so sample-boundary discontinuities do not create
81	 * audible clicks.
82	 */
83	
84	static void fill_sine(FAR int16_t *dst, size_t nsamples,
85	                      FAR double *phase)
86	{
87	  const double step = 2.0 * M_PI * g_freq_hz / (double)g_sample_rate;
88	  const int16_t amp = 20000;   /* headroom below full-scale.            */
89	  size_t i;
90	
91	  for (i = 0; i < nsamples; i += g_channels)
92	    {
93	      int16_t s = (int16_t)(amp * sin(*phase));
94	      int c;
95	
96	      for (c = 0; c < g_channels; c++)
97	        {
98	          dst[i + c] = s;
99	        }
100	
101	      *phase += step;
102	      if (*phase >= 2.0 * M_PI)
103	        {
104	          *phase -= 2.0 * M_PI;
105	        }
106	    }
107	}
108	
109	static int set_volume(int fd, int volume)
110	{
111	  struct audio_caps_desc_s cap;
112	
113	  memset(&cap, 0, sizeof(cap));
114	  cap.caps.ac_len            = sizeof(struct audio_caps_s);
115	  cap.caps.ac_type           = AUDIO_TYPE_FEATURE;
116	  cap.caps.ac_format.hw      = AUDIO_FU_VOLUME;
117	  cap.caps.ac_controls.hw[0] = (uint16_t)volume;
118	  return ioctl(fd, AUDIOIOC_CONFIGURE, (unsigned long)&cap);
119	}
