125	static void bk7258_gpio_clear_irq_locked(unsigned int pin)
126	{
127	  uint32_t regval;
128	  uint32_t bit;
129	
130	  regval = getreg32(BK7258_GPIO_CFG(pin));
131	  regval |= BK7258_GPIO_INT_CLEAR;
132	  putreg32(regval, BK7258_GPIO_CFG(pin));
133	
134	  bit = UINT32_C(1) << (pin & 31);
135	  putreg32(bit, pin < 32 ? BK7258_GPIO_INT_STATUS0 :
136	                            BK7258_GPIO_INT_STATUS1);
137	}
