190	int bk7258_gpio_config_input(unsigned int pin,
191	                             enum bk7258_gpio_pull_e pull)
192	{
193	  irqstate_t flags;
194	  uint32_t regval;
195	
196	  if (!bk7258_gpio_valid(pin) || pull < BK7258_GPIO_PULL_NONE ||
197	      pull > BK7258_GPIO_PULL_DOWN)
198	    {
199	      return -EINVAL;
200	    }
201	
202	  flags = enter_critical_section();
203	  bk7258_gpio_select_func_locked(pin);
204	
205	  regval  = getreg32(BK7258_GPIO_CFG(pin));
206	  regval &= ~(BK7258_GPIO_CFG_MODE_MASK |
207	              BK7258_GPIO_CFG_PULL_MASK |
208	              BK7258_GPIO_CFG_SECOND_FUNC);
209	  regval |= BK7258_GPIO_CFG_MODE_INPUT;
210	
211	  switch (pull)
212	    {
213	      case BK7258_GPIO_PULL_UP:
214	        regval |= BK7258_GPIO_CFG_PULL_UP;
215	        break;
216	
217	      case BK7258_GPIO_PULL_DOWN:
218	        regval |= BK7258_GPIO_CFG_PULL_DOWN;
219	        break;
220	
221	      default:
222	        break;
223	    }
224	
225	  putreg32(regval, BK7258_GPIO_CFG(pin));
226	  leave_critical_section(flags);
227	  return OK;
228	}
