442	void bk7258_gpio_periph(unsigned int pin, unsigned int func)
443	{
444	  irqstate_t flags;
445	  uint32_t regval;
446	
447	  if (!bk7258_gpio_valid(pin))
448	    {
449	      return;
450	    }
451	
452	  flags  = enter_critical_section();
453	  regval = getreg32(BK7258_GPIO_CFG(pin));
454	  regval &= ~(BK7258_GPIO_CFG_MODE_MASK | BK7258_GPIO_CFG_PULL_MASK);
455	  regval |= BK7258_GPIO_CFG_MODE_DIS | BK7258_GPIO_CFG_SECOND_FUNC;
456	  putreg32(regval, BK7258_GPIO_CFG(pin));
457	
458	  regval  = getreg32(BK7258_SYS_GPIO_FUNC(pin));
459	  regval &= ~BK7258_GPIO_FUNC_MASK(pin);
460	  regval |= (func & UINT32_C(0xf)) << (((uint32_t)pin & 7) << 2);
461	  putreg32(regval, BK7258_SYS_GPIO_FUNC(pin));
462	  leave_critical_section(flags);
463	}
