465	int bk7258_gpio_irq_initialize(void)
466	{
467	#ifndef CONFIG_BK7258_COMPONENT_AP
468	  return -ENOSYS;
469	#else
470	  irqstate_t flags;
471	  int ret;
472	
473	  flags = enter_critical_section();
474	  if (g_gpio_irq_initialized)
475	    {
476	      leave_critical_section(flags);
477	      return OK;
478	    }
479	
480	  ret = irq_attach(BK7258_IRQ_GPIO, bk7258_gpio_interrupt, NULL);
481	  if (ret == OK)
482	    {
483	      bk7258_gpio_route_irq();
484	      up_enable_irq(BK7258_IRQ_GPIO);
485	      g_gpio_irq_initialized = true;
486	    }
487	
488	  leave_critical_section(flags);
489	  return ret;
490	#endif
491	}
