493	void bk7258_gpio_dispatch(void *context)
494	{
495	#ifdef CONFIG_BK7258_COMPONENT_AP
496	  uint32_t pending[2];
497	  unsigned int pin;
498	
499	  pending[0] = getreg32(BK7258_GPIO_INT_STATUS0);
500	  pending[1] = getreg32(BK7258_GPIO_INT_STATUS1) &
501	               BK7258_GPIO_STATUS1_MASK;
502	
503	  for (pin = 0; pin < GPIO_IRQ_SLOTS; pin++)
504	    {
505	      struct bk7258_gpio_irq_s *entry;
506	      irqstate_t flags;
507	      xcpt_t handler;
508	      void *arg;
509	      uint32_t bit;
510	      unsigned int bank;
511	
512	      bank = pin >> 5;
513	      bit  = UINT32_C(1) << (pin & 31);
514	      if ((pending[bank] & bit) == 0)
515	        {
516	          continue;
517	        }
518	
519	      flags = enter_critical_section();
520	      entry = &g_gpio_irqs[pin];
521	
522	      if (entry->rising && entry->falling)
523	        {
524	          /* Rearm before reporting this snapshot's pending event.  A net
525	           * level change during rearm makes the hardware assert a new pending
526	           * bit and schedule another shared IRQ; this dispatch still invokes
527	           * the handler only once for the original pending bit.
528	           */
529	
530	          bk7258_gpio_rearm_opposite_level_locked(pin);
531	        }
532	      else
533	        {
534	          bk7258_gpio_clear_irq_locked(pin);
535	        }
536	
537	      handler = entry->handler;
538	      arg     = entry->arg;
539	      leave_critical_section(flags);
540	
541	      if (handler != NULL)
542	        {
543	          handler((int)pin, context, arg);
544	        }
545	    }
546	#else
547	  /* Source 55 and aggregate pending state belong to AP. */
548	
549	  (void)context;
550	#endif
551	}
