if (g_mclk_mode)
  {
    static const char *const clk_name[] = {"XTAL", "APLL"};
    volatile uint32_t *p_gpio28_cfg = (volatile uint32_t *)0x44000470u;
    volatile uint32_t *p_func28    = (volatile uint32_t *)0x440100ccu;
    volatile uint32_t *p_clkdiv1   = (volatile uint32_t *)0x44010020u;
    volatile uint32_t *p_clkdiv2   = (volatile uint32_t *)0x44010024u;
    volatile uint32_t *p_devclk    = (volatile uint32_t *)0x44010030u;
    volatile uint32_t *p_devclk2   = (volatile uint32_t *)0x44010034u;
    struct bk7258_dac_cfg_s dac_cfg;

    /* Mux GPIO28 -> I2S1_MCLK (AF2): per-pin cfg mode=DIS + second-func;
     * SYS_GPIO_FUNC field bits[19:16]=1. */
    *p_gpio28_cfg = (*p_gpio28_cfg & ~UINT32_C(0x3c)) | UINT32_C(0x48);
    *p_func28     = (*p_func28     & ~UINT32_C(0x000f0000)) | UINT32_C(0x00010000);
    /* Gate on I2S + I2S1 functional clocks. */
    *p_devclk  |= UINT32_C(1) << 16;   /* i2s_cken */
    *p_devclk2 |= UINT32_C(1) << 1;    /* i2s1_cken */

    dac_cfg.samp_rate = (uint32_t)g_sample_rate;
    dac_cfg.channel   = BK7258_DAC_CHL_LR;
    dac_cfg.work_mode = BK7258_DAC_WORK_DIFFEN;
    dac_cfg.gain      = 0;

    ret = bk7258_aud_subsystem_init();
    if (ret < 0) { fprintf(stderr, "[bk] MCLK subsystem init failed: %d\n", ret); goto cleanup; }

    for (int phase = 0; phase < 2; phase++)
      {
        uint32_t sel = phase != 0;
        bk7258_dac_reset_data_path();
        dac_cfg.use_apll = sel != 0;
        ret = bk7258_dac_configure(&dac_cfg);
        if (ret < 0) { fprintf(stderr, "[bk] MCLK %s configure failed: %d\n", clk_name[phase], ret); bk7258_dac_deinit(); goto cleanup; }
        /* Point I2S/I2S1 MCLK at the same functional clock: cksel_i2s (bit24)
         * + cksel_i2s1 (bit11). 0=XTAL(26M) 1=APLL(98.304M). */
        if (sel) { *p_clkdiv1 |= UINT32_C(1) << 24; *p_clkdiv2 |= UINT32_C(1) << 11; }
        else     { *p_clkdiv1 &= ~(UINT32_C(1) << 24); *p_clkdiv2 &= ~(UINT32_C(1) << 11); }
        printf("[bk] MCLK phase=%s cksel_i2s=%lu cksel_i2s1=%lu cksel_aud=%lu clkdiv1=%08lx clkdiv2=%08lx\n",
               clk_name[phase], (unsigned long)((*p_clkdiv1 >> 24) & 1),
               (unsigned long)((*p_clkdiv2 >> 11) & 1), (unsigned long)((*p_clkdiv1 >> 25) & 1),
               (unsigned long)*p_clkdiv1, (unsigned long)*p_clkdiv2);
        printf("[bk] MCLK -> measure GPIO28 (P28 pad) now: expect %s\n",
               sel ? "~98.304 MHz (APLL)" : "~26 MHz (XTAL)");
        fflush(stdout);
        usleep(3000000);
      }
    bk7258_dac_deinit();
    printf("[bk] MCLK done\n"); fflush(stdout);
    ret = 0;
    goto cleanup;
  }
