160	bk_err_t bk_aud_adc_set_samp_rate(uint32_t samp_rate)
161	{
162		AUD_ADC_RETURN_ON_NOT_INIT();
163	
164	#if CONFIG_SOC_BK7236XX
165		/* get audio clock config */
166		if (1 == aud_hal_get_audio_config_apll_sel()) {
167			/* config apll */
168			sys_drv_apll_en(1);
169			//set apll clock config
170			if (samp_rate == 11025 || samp_rate == 22050 || samp_rate == 44100) {
171				sys_drv_apll_cal_val_set(0x88AF2EC9);
172			} else {
173				sys_drv_apll_cal_val_set(0x8973CA6F);
174			}
175			sys_drv_apll_config_set(0xC2A0AE86);
176			sys_drv_apll_spi_trigger_set(1);
177			delay(10);
178			sys_drv_apll_spi_trigger_set(0);
179		}
180	#endif
181	
182		/* disable dac handset bit again, to make sure this bit unset */
183		aud_hal_set_extend_cfg_adc_fracmod_manual(0x0);
184	
185		switch(samp_rate)
186		{
187			case 8000:
188				aud_hal_set_audio_config_samp_rate_adc(0x0);
189				break;
190	
191			case 16000:
192				aud_hal_set_audio_config_samp_rate_adc(0x1);
193				break;
194	
195			case 44100:
196				aud_hal_set_audio_config_samp_rate_adc(0x2);
197				break;
198	
199			case 48000:
200				aud_hal_set_audio_config_samp_rate_adc(0x3);
201				break;
202	
203			case 11025:
204				aud_hal_set_extend_cfg_adc_fracmod_manual(0x1);
205				aud_hal_set_adc_fracmod_value(CONST_DIV_44_1K);
206				aud_hal_set_audio_config_samp_rate_adc(0x2);
207				break;
208	
209			case 12000:
210				aud_hal_set_extend_cfg_adc_fracmod_manual(0x1);
211				aud_hal_set_adc_fracmod_value(CONST_DIV_48K);
212				aud_hal_set_audio_config_samp_rate_adc(0x3);
213				break;
214	
215			case 22050:
216				aud_hal_set_extend_cfg_adc_fracmod_manual(0x1);
217				aud_hal_set_adc_fracmod_value(CONST_DIV_44_1K >> 1);
218				aud_hal_set_audio_config_samp_rate_adc(0x2);
219				break;
220	
221			case 24000:
222				aud_hal_set_extend_cfg_adc_fracmod_manual(0x1);
223				aud_hal_set_adc_fracmod_value(CONST_DIV_48K >> 1);
224				aud_hal_set_audio_config_samp_rate_adc(0x3);
225				break;
226	
227			case 32000:
228				aud_hal_set_extend_cfg_adc_fracmod_manual(0x1);
229				aud_hal_set_adc_fracmod_value(CONST_DIV_32K);
230				aud_hal_set_audio_config_samp_rate_adc(0x3);
231				break;
232	
233			default:
234				LOGE("%s, not support sample rate: %d, line: %d \n", __func__, samp_rate, __LINE__);
235				return BK_FAIL;
236				break;
237		}
238	
239		return BK_OK;
240	}
