730	void bk7258_dac_reset_data_path(void)
731	{
732	  irqstate_t flags;
733	
734	  /* Mirror AVDK's soft-reset pulse: toggle only the self-clearing
735	   * soft_reset bit.  Never write clk_gate (bit1) — leaving it at its
736	   * working default (0) is what keeps the DAC/FIFO functional clock
737	   * alive; asserting bit1 gates the FIFO off and no FPORT write is ever
738	   * accepted (proven by the FPORT-KICK probe).
739	   */
740	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
741	  putreg32(getreg32(BK7258_AUD_CLK_CONTROL) | AUD_CLK_CTRL_SOFT_RESET,
742	           BK7258_AUD_CLK_CONTROL);
743	  up_udelay(10);
744	  putreg32(getreg32(BK7258_AUD_CLK_CONTROL) & ~AUD_CLK_CTRL_SOFT_RESET,
745	           BK7258_AUD_CLK_CONTROL);
746	  g_bk7258_dac_configured = false;
747	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
748	}
