155	static uint8_t bk7258_volume_to_gain(uint8_t volume)
156	{
157	  if (volume == 0)
158	    {
159	      return 0;
160	    }
161	
162	  if (volume >= 100)
163	    {
164	      return BK7258_AUDIO_MAX_DAC_GAIN;
165	    }
166	
167	  return (uint8_t)(((uint32_t)volume * BK7258_AUDIO_MAX_DAC_GAIN) / 100u);
168	}
