212	/* Queue LPWORK while holding priv->lock.  Pairing the closing check and
213	 * work_queue() under the same lock ensures shutdown either prevents a new
214	 * queue operation or observes an already queued item that cancel_sync can
215	 * cover.  work_queue() is IRQ-safe and does not sleep.
216	 */
217	
218	static void bk7258_schedule_worker_locked(FAR struct bk7258_audio_s *priv)
219	{
220	  if (!priv->closing)
221	    {
222	      (void)work_queue(LPWORK, &priv->work, bk7258_worker, priv, 0);
223	    }
224	}
225	
226	/* Close the run gate and detach every buffer affected by an asynchronous
227	 * failure.  recover_after_fault distinguishes a synchronous initial-start
228	 * failure from a runtime fault that requires stop plus OUTPUT configure.
229	 * Must be called with priv->lock held.
230	 */
231	
232	static void bk7258_fault_locked(FAR struct bk7258_audio_s *priv, int error,
233	                                bool recover_after_fault)
234	{
235	  FAR struct ap_buffer_s *apb;
236	
237	  priv->dac_running = false;
238	  priv->dma_active = false;
239	  priv->faulted = true;
240	  priv->fault_pending = true;
241	  priv->recover_after_fault = recover_after_fault;
242	  priv->complete_pending = false;
243	  priv->underrun_pending = true;
244	  priv->final_seen = false;
245	
246	  priv->dma_error = error;
247	
248	  while ((apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq)) != NULL)
249	    {
250	      dq_addlast(&apb->dq_entry, &priv->failq);
251	    }
252	}
253	
254	/* Kick off a DMA transfer for the buffer at the head of pendq.  Must be
255	 * called with priv->lock held.  dma_active prevents the same head from being
256	 * programmed twice.  Returns zero if no buffer is queued/already active or
257	 * the transfer starts successfully; otherwise returns a negated errno.
258	 */
259	
260	static int bk7258_start_next_locked(FAR struct bk7258_audio_s *priv)
261	{
262	  FAR struct ap_buffer_s *apb;
263	  struct bk7258_dma_m2p_cfg_s cfg;
264	  int ret;
265	
266	  if (priv->closing || priv->stopping || priv->faulted ||
267	      priv->fault_pending || !priv->dac_running || priv->dma_active)
268	    {
269	      return OK;
270	    }
271	
272	  apb = (FAR struct ap_buffer_s *)dq_peek(&priv->pendq);
273	  if (apb == NULL)
274	    {
275	      return OK;
276	    }
277	
278	  cfg.buf          = (uintptr_t)apb->samp;
279	  cfg.buf_len      = apb->nbytes;
280	  cfg.dest         = bk7258_dac_fifo_addr();
281	  cfg.dest_req_mux = BK7258_DMA_REQ_AUDIO_DAC;
282	  /* The DAC FIFO port is a single 32-bit register (AUD_DAC_FPORT).  Each
283	   * word is one stereo frame {R:16, L:16} or two mono samples.  Both
284	   * source and destination widths must be 32-bit so the DMA engine drops
285	   * exactly one word into the FIFO per transfer beat.  Using 16-bit width
286	   * would leave the FIFO half-loaded and the "finish" interrupt would
287	   * never fire.
288	   */
289	
290	  cfg.src_width    = BK7258_DMA_WIDTH_32;
291	  cfg.dst_width    = BK7258_DMA_WIDTH_32;
292	  /* AVDK's reference audio path uses REPEAT + src loop instead of a
293	   * one-shot transfer.  Empirical trace with one_shot=true showed the DMA
294	   * moves only 3 words then stalls (remain_len frozen).  In REPEAT mode
295	   * the engine keeps consuming DREQ pulses from the DAC FIFO until
296	   * transfer_len is reached, which matches the peripheral request timing
297	   * BK7258's audio block appears to expect.
298	   */
299	
300	  cfg.one_shot     = false;
301	  cfg.callback     = bk7258_audio_dma_cb;
302	  cfg.arg          = priv;
303	
304	  /* Clean the source buffer out of D-cache; GDMA reads from RAM. */
305	
306	  up_clean_dcache((uintptr_t)apb->samp,
307	                  (uintptr_t)apb->samp + apb->nbytes);
308	
309	  ret = bk7258_gdma_start_m2p(priv->dma_ch, &cfg);
310	  if (ret < 0)
311	    {
312	      AUD_ERR("gdma_start_m2p failed: %d", ret);
313	      return ret;
314	    }
315	
316	  priv->dma_active = true;
317	  return OK;
318	}
319	
320	/* LPWORK is deliberately not a queue advancer.  It only makes an
321	 * asynchronous fault safe, returns completed/failed buffers, and emits
322	 * deferred upper-half notifications.
323	 */
324	
325	static void bk7258_worker(FAR void *arg)
326	{
327	  FAR struct bk7258_audio_s *priv = arg;
328	  FAR struct ap_buffer_s *apb;
329	  irqstate_t flags;
330	  bool complete;
331	  bool fault_underrun;
332	  bool fault_work;
333	  bool underrun;
334	  int error;
335	  int pa_ret;
336	
337	  flags = spin_lock_irqsave(&priv->lock);
338	  if (priv->closing)
339	    {
340	      spin_unlock_irqrestore(&priv->lock, flags);
341	      return;
342	    }
343	
344	  error = priv->dma_error < 0 ? priv->dma_error : -EIO;
345	  fault_work = priv->fault_pending;
346	  spin_unlock_irqrestore(&priv->lock, flags);
347	
348	  if (fault_work)
349	    {
350	      if (priv->configured)
351	        {
352	          (void)bk7258_dac_mute(true);
353	        }
354	
355	      if (priv->dma_ch >= 0)
356	        {
357	          bk7258_gdma_stop(priv->dma_ch);
358	        }
359	
360	      bk7258_dac_stop();
361	      pa_ret = bk7258_pa_disable();
362	      if (pa_ret < 0)
363	        {
364	          AUD_ERR("PA disable after DMA fault failed: %d", pa_ret);
365	        }
366	
367	      flags = spin_lock_irqsave(&priv->lock);
368	      priv->fault_pending = false;
369	      spin_unlock_irqrestore(&priv->lock, flags);
370	    }
371	
372	  for (; ; )
373	    {
374	      flags = spin_lock_irqsave(&priv->lock);
375	      if (priv->closing)
376	        {
377	          spin_unlock_irqrestore(&priv->lock, flags);
378	          return;
379	        }
380	
381	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->doneq);
382	      spin_unlock_irqrestore(&priv->lock, flags);
383	
384	      if (apb == NULL)
385	        {
386	          break;
387	        }
388	
389	      bk7258_notify_dequeue(priv, apb, OK);
390	    }
391	
392	  for (; ; )
393	    {
394	      flags = spin_lock_irqsave(&priv->lock);
395	      if (priv->closing)
396	        {
397	          spin_unlock_irqrestore(&priv->lock, flags);
398	          return;
399	        }
400	
401	      /* A fault raised after this worker started must be made hardware-safe
402	       * by the requeued invocation before any error DEQUEUE is emitted.
403	       */
404	
405	      if (priv->fault_pending)
406	        {
407	          spin_unlock_irqrestore(&priv->lock, flags);
408	          return;
409	        }
410	
411	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->failq);
412	      spin_unlock_irqrestore(&priv->lock, flags);
413	
414	      if (apb == NULL)
415	        {
416	          break;
417	        }
418	
419	      bk7258_notify_dequeue(priv, apb, error);
420	    }
421	
422	  flags = spin_lock_irqsave(&priv->lock);
423	  if (priv->closing)
424	    {
425	      spin_unlock_irqrestore(&priv->lock, flags);
426	      return;
427	    }
428	
429	  fault_underrun = priv->faulted || fault_work;
430	  underrun = priv->underrun_pending;
431	  priv->underrun_pending = false;
432	
433	  /* A synchronous initial-start failure is recoverable once hardware is
434	   * safe and every accepted buffer has completed its error callback.  Keep
435	   * faulted asserted during those callbacks so upper-half refill attempts
436	   * are rejected.  Runtime faults never set recover_after_fault.
437	   */
438	
439	  if (priv->recover_after_fault && !priv->fault_pending &&
440	      dq_peek(&priv->failq) == NULL)
441	    {
442	      priv->recover_after_fault = false;
443	      priv->faulted = false;
444	      priv->dma_error = OK;
445	    }
446	
447	  if (priv->final_seen && !priv->faulted && !priv->dma_active &&
448	      dq_peek(&priv->pendq) == NULL)
449	    {
450	      priv->final_seen = false;
451	      priv->complete_pending = true;
452	    }
453	
454	  complete = priv->complete_pending && !priv->dma_active &&
455	             dq_peek(&priv->pendq) == NULL &&
456	             dq_peek(&priv->doneq) == NULL &&
457	             dq_peek(&priv->failq) == NULL;
458	  if (complete)
459	    {
460	      priv->complete_pending = false;
461	    }
462	
463	  spin_unlock_irqrestore(&priv->lock, flags);
464	
465	  if (underrun)
466	    {
467	      bk7258_notify_underrun(priv, fault_underrun ? error : -EPIPE);
468	    }
469	
470	  if (complete)
471	    {
472	      bk7258_notify_complete(priv);
473	    }
474	}
475	
476	/* DMA IRQ callback.  IRQ completion and enqueue are the only queue
477	 * advancers.  Faults only close the run gate and defer all sleeping, PA,
478	 * hardware-stop and upper-half work to LPWORK.
479	 */
480	
481	void bk7258_audio_dma_cb(int ch, uint32_t event, FAR void *arg)
482	{
483	  FAR struct bk7258_audio_s *priv = arg;
484	  FAR struct ap_buffer_s *apb;
485	  irqstate_t flags;
486	  bool need_worker = false;
487	  int ret;
488	
489	  (void)ch;
490	
491	  flags = spin_lock_irqsave(&priv->lock);
492	
493	  if ((event & BK7258_DMA_EVENT_BUS_ERROR) != 0u)
494	    {
495	      if (priv->dac_running || priv->dma_active)
496	        {
497	          AUD_ERR("DMA bus error");
498	          bk7258_fault_locked(priv, -EIO, false);
499	          need_worker = true;
500	        }
501	    }
502	  else if ((event & BK7258_DMA_EVENT_FULL) != 0u && priv->dma_active)
503	    {
504	      apb = (FAR struct ap_buffer_s *)dq_remfirst(&priv->pendq);
505	      priv->dma_active = false;
506	      if (apb != NULL)
507	        {
508	          dq_addlast(&apb->dq_entry, &priv->doneq);
509	          need_worker = true;
510	        }
511	
512	      if (priv->dac_running && !priv->closing && !priv->stopping &&
513	          !priv->faulted)
514	        {
515	          ret = bk7258_start_next_locked(priv);
516	          if (ret < 0)
517	            {
518	              bk7258_fault_locked(priv, ret, false);
519	              need_worker = true;
520	            }
521	          else if (!priv->dma_active)
522	            {
523	              if (priv->final_seen)
524	                {
525	                  priv->complete_pending = true;
526	                }
527	              else
528	                {
529	                  priv->underrun_pending = true;
530	                }
531	
532	              need_worker = true;
533	            }
534	        }
535	    }
536	
537	  if (need_worker)
538	    {
539	      bk7258_schedule_worker_locked(priv);
540	    }
541	
542	  spin_unlock_irqrestore(&priv->lock, flags);
543	}
