762	void bk7258_dac_deinit(void)
763	{
764	  uint32_t v;
765	
766	  bk7258_dac_stop();
767	  (void)bk7258_dac_mute(true);
768	
769	  /* Reverse the analog power-up sequence.  Keep the ana_reg defaults in
770	   * place so a future bk7258_dac_configure() does not have to re-run the
771	   * whole subsystem init.
772	   */
773	
774	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_DACLEN_BIT, 0x1u, 0);
775	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG21, ANA_REG21_ENIDACL_BIT, 0x1u, 0);
776	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_LENDCOC_BIT, 0x1u, 0);
777	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG20, ANA_REG20_DACDRVEN_BIT, 0x1u, 0);
778	
779	  /* Restore the vendor deinit clock baseline: select XTAL in both the SYS
780	   * mux and AUD block, clear the APLL-only DMIC divider, then power APLL
781	   * down.  This makes the next configure independent of the previous one.
782	   */
783	
784	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
785	  v &= ~AUD_AUDIO_CFG_APLL_SEL;
786	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
787	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
788	                      SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
789	                          << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
790	                      0u);
791	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
792	                      UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
793	                      0u);
794	  (void)bk7258_ana_reg_bit(BK7258_ANA_REG_APLL_PWD,
795	                           ANA_REG5_PWDAUDPLL_BIT, 0x1u, 1u);
796	
797	  g_bk7258_dac_use_apll  = false;
798	  g_bk7258_dac_configured = false;
799	}
