81	/* Fill an S16_LE buffer with a bounded sine wave at g_freq_hz.  phase is
82	 * carried across buffers so sample-boundary discontinuities do not create
83	 * audible clicks.
84	 */
85	
86	static void fill_sine(FAR int16_t *dst, size_t nsamples,
87	                      FAR double *phase)
88	{
89	  const double step = 2.0 * M_PI * g_freq_hz / (double)g_sample_rate;
90	  const int16_t amp = 20000;   /* headroom below full-scale.            */
91	  size_t i;
92	
93	  for (i = 0; i < nsamples; i += g_channels)
94	    {
95	      int16_t s = (int16_t)(amp * sin(*phase));
96	      int c;
97	
98	      for (c = 0; c < g_channels; c++)
99	        {
100	          dst[i + c] = s;
101	        }
102	
103	      *phase += step;
104	      if (*phase >= 2.0 * M_PI)
105	        {
106	          *phase -= 2.0 * M_PI;
107	        }
108	    }
109	}
