    reg_value |= ((value & AUD_CLK_CONTROL_CLK_GATE_MASK) << AUD_CLK_CONTROL_CLK_GATE_POS);
    REG_WRITE(AUD_CLK_CONTROL_ADDR,reg_value);
}

