121	 * Private Data
122	 ****************************************************************************/
123	
124	static bool           g_bk7258_aud_subsys_ready;
125	static bool           g_bk7258_dac_configured;
126	static spinlock_t     g_bk7258_aud_lock = SP_UNLOCKED;
127	
128	/* Cached configuration so bk7258_dac_set_sample_rate() can honour the APLL
129	 * cal-value swap for the 44.1k family.
130	 */
131	
132	static bool           g_bk7258_dac_use_apll;
