250	/****************************************************************************
251	 * Public Functions
252	 ****************************************************************************/
253	
254	int bk7258_aud_subsystem_init(void)
255	{
256	  irqstate_t flags;
257	  int ret = OK;
258	
259	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
260	  if (g_bk7258_aud_subsys_ready)
261	    {
262	      spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
263	      return OK;
264	    }
265	
266	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
267	
268	  /* CP owns the shared SYS power and SRAM controls and clears them while AP
269	   * is held in reset.  AP must only validate that handoff: writing these
270	   * registers here would race CP power management through whole-word RMWs.
271	   * Fail closed before publishing subsystem readiness if the handoff did not
272	   * take effect.
273	   */
274	
275	  {
276	    uint32_t power = getreg32(BK7258_SYS_POWER_WAKEUP);
277	    uint32_t mem_ctrl1 = getreg32(BK7258_SYS_DEV_MEM_CTRL1);
278	    uint32_t mem_ctrl2 = getreg32(BK7258_SYS_DEV_MEM_CTRL2);
279	
280	    if ((power & BK7258_SYS_AUDP_POWER_DOWN) != 0 ||
281	        (mem_ctrl1 & BK7258_SYS_AUD_MEM_LOW_POWER) != 0 ||
282	        (mem_ctrl2 & BK7258_SYS_AUD_MEM_LOW_POWER) != 0)
283	      {
284	        auderr("BK7258: CP audio wake handoff invalid: "
285	               "pwr=%08lx sd=%08lx ds=%08lx\n",
286	               (unsigned long)power,
287	               (unsigned long)mem_ctrl1,
288	               (unsigned long)mem_ctrl2);
289	        return -EIO;
290	      }
291	  }
292	
293	  /* §2.1 step 2/3: start from XTAL and gate the audio clock on.  The audio
294	   * clock mux is programmed later by bk7258_dac_configure().
295	   */
296	
297	  bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
298	                      SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
299	                          << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
300	                      0u);
301	  bk7258_sys_reg_bits(SYS_CPU_DEVICE_CLK_EN,
302	                      UINT32_C(1) << SYS_CPU_DEVICE_CLK_AUD_CKEN_BIT,
303	                      UINT32_C(1) << SYS_CPU_DEVICE_CLK_AUD_CKEN_BIT);
304	
305	  /* §2.1 step 4: the AUD-block interrupt line is intentionally NOT gated
306	   * here.  Playback goes through GDMA; the driver does not attach any
307	   * handler to BK7258_IRQ_AUDIO, so leaving the sys-ctrl CPU int_en bit
308	   * clear avoids delivering an aggregate audio IRQ that nobody consumes.
309	   */
310	
311	  /* §2.1 step 5: audio block soft-reset via AUD_CLK_CONTROL.
312	   *
313	   * AVDK's bk_aud_driver_init() does only an RMW pulse on bit0
314	   * (soft_reset=1, self-clearing) and never writes bit1 (clk_gate).  The
315	   * audio subsystem works at the hardware default clk_gate=0.
316	   *
317	   * The initial bring-up here wrote SOFT_RESET|CLK_GATE (bit1=1) and
318	   * then CLK_GATE, leaving bit1 asserted.  The FPORT-KICK probe proved
319	   * this starves the FIFO: with bit1=1 the DAC/FIFO functional clock is
320	   * gated off, so neither CPU nor GDMA writes to DAC_FPORT were ever
321	   * accepted (FIFO_STATUS stayed all-EMPTY across 32 rapid writes and
322	   * a full 200 ms GDMA transfer, remain_len frozen at 4092).  Register
323	   * read/write still worked because the APB access clock is independent.
324	   *
325	   * Mirror AVDK exactly: touch only the self-clearing soft_reset bit,
326	   * leave clk_gate at its working default (0).
327	   */
328	
329	  putreg32(getreg32(BK7258_AUD_CLK_CONTROL) | AUD_CLK_CTRL_SOFT_RESET,
330	           BK7258_AUD_CLK_CONTROL);
331	  up_udelay(10);
332	  putreg32(getreg32(BK7258_AUD_CLK_CONTROL) & ~AUD_CLK_CTRL_SOFT_RESET,
333	           BK7258_AUD_CLK_CONTROL);
334	
335	  /* §2.1 step 6: apply the pre-computed ana_reg defaults.  These are the
336	   * exact values AVDK's ana_regNN_value_cal() functions produce on
337	   * SOC_BK7236XX; changing them alters bias current, VCM and DAC common
338	   * mode and MUST be re-derived from silicon test data if touched.
339	   */
340	
341	  ret = bk7258_ana_reg_write(BK7258_ANA_REG18, BK7258_ANA_REG18_DEFAULT);
342	  if (ret < 0)
343	    {
344	      goto fail;
345	    }
346	
347	  ret = bk7258_ana_reg_write(BK7258_ANA_REG19, BK7258_ANA_REG19_DEFAULT);
348	  if (ret < 0)
349	    {
350	      goto fail;
351	    }
352	
353	  ret = bk7258_ana_reg_write(BK7258_ANA_REG20, BK7258_ANA_REG20_DEFAULT);
354	  if (ret < 0)
355	    {
356	      goto fail;
357	    }
358	
359	  ret = bk7258_ana_reg_write(BK7258_ANA_REG21, BK7258_ANA_REG21_DEFAULT);
360	  if (ret < 0)
361	    {
362	      goto fail;
363	    }
364	
365	  ret = bk7258_ana_reg_write(BK7258_ANA_REG27, BK7258_ANA_REG27_DEFAULT);
366	  if (ret < 0)
367	    {
368	      goto fail;
369	    }
370	
371	  /* §2.1 step 7: enable the audio bias network AFTER the ana_reg defaults
372	   * have latched.
373	   */
374	
375	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG18,
376	                           ANA_REG18_ENAUDBIAS_BIT, 0x1u, 1);
377	  if (ret < 0)
378	    {
379	      goto fail;
380	    }
381	
382	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
383	  g_bk7258_aud_subsys_ready = true;
384	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
385	
386	  audinfo("BK7258: audio subsystem initialised\n");
387	  return OK;
388	
389	fail:
390	  auderr("BK7258: audio subsystem init failed: %d\n", ret);
391	  return ret;
392	}
393	
394	int bk7258_dac_configure(const struct bk7258_dac_cfg_s *cfg)
395	{
396	  irqstate_t flags;
397	  uint32_t v;
398	  int ret;
399	
400	  if (cfg == NULL)
401	    {
402	      return -EINVAL;
403	    }
404	
405	  if (!g_bk7258_aud_subsys_ready)
406	    {
407	      ret = bk7258_aud_subsystem_init();
408	      if (ret < 0)
409	        {
410	          return ret;
411	        }
412	    }
413	
414	  g_bk7258_dac_use_apll = cfg->use_apll;
415	
416	  /* §2.2 clock select. */
417	
418	  if (cfg->use_apll)
419	    {
420	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
421	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
422	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
423	                          UINT32_C(1) << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT);
424	
425	      ret = bk7258_apll_program(BK7258_APLL_CAL_VAL_48K);
426	      if (ret < 0)
427	        {
428	          return ret;
429	        }
430	
431	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
432	      v |= AUD_AUDIO_CFG_APLL_SEL;
433	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
434	
435	      /* Divide DMIC clock so it does not steal APLL bandwidth. */
436	
437	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE2,
438	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT,
439	                          UINT32_C(1) << SYS_CLK_DIV_MODE2_DMIC_DIV_BIT);
440	    }
441	  else
442	    {
443	      bk7258_sys_reg_bits(SYS_CLK_DIV_MODE1,
444	                          SYS_CLK_DIV_MODE1_CKSEL_AUD_MASK
445	                              << SYS_CLK_DIV_MODE1_CKSEL_AUD_BIT,
446	                          0u);
447	
448	      v = getreg32(BK7258_AUD_AUDIO_CONFIG);
449	      v &= ~AUD_AUDIO_CFG_APLL_SEL;
450	      putreg32(v, BK7258_AUD_AUDIO_CONFIG);
451	    }
452	
453	  /* §2.3 step 4: DAC analog path power-up.  On BK7258 (SOC_BK7236XX) the
454	   * BK7256-era right-channel/vdd rails are not-supported no-ops in AVDK;
455	   * we only drive the fields that actually map to silicon.
456	   *
457	   *   dac_bias_en  → ana_reg21[enbs]        (not exposed here, latched by
458	   *                                          the ana_reg21 default value)
459	   *   dac_drv_en   → ana_reg20[dacdrven]
460	   *   dac_dcoc_en  → ana_reg20[lendcoc]
461	   *   dac_idac_en  → ana_reg21[enidacl]
462	   *   dacl_en      → ana_reg20[daclen]
463	   *   diffen       → ana_reg20[diffen]
464	   */
465	
466	  /* AVDK aud_dac_driver.c:81..87 explicitly flips these four bits in this
467	   * order.  ana_reg21.enbs (dac bias) is NOT part of the reset default
468	   * value we programmed earlier and MUST be raised now.
469	   */
470	
471	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG21,
472	                           ANA_REG21_ENBS_BIT, 0x1u, 1);
473	  if (ret < 0)
474	    {
475	      return ret;
476	    }
477	
478	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
479	                           ANA_REG20_DACDRVEN_BIT, 0x1u, 1);
480	  if (ret < 0)
481	    {
482	      return ret;
483	    }
484	
485	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
486	                           ANA_REG20_LENDCOC_BIT, 0x1u, 1);
487	  if (ret < 0)
488	    {
489	      return ret;
490	    }
491	
492	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG21,
493	                           ANA_REG21_ENIDACL_BIT, 0x1u, 1);
494	  if (ret < 0)
495	    {
496	      return ret;
497	    }
498	
499	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
500	                           ANA_REG20_DACLEN_BIT, 0x1u, 1);
501	  if (ret < 0)
502	    {
503	      return ret;
504	    }
505	
506	  /* §2.3 step 6: differential vs single-ended. */
507	
508	  ret = bk7258_ana_reg_bit(BK7258_ANA_REG20,
509	                           ANA_REG20_DIFFEN_BIT, 0x1u,
510	                           cfg->work_mode == BK7258_DAC_WORK_DIFFEN
511	                                             ? 1u : 0u);
512	  if (ret < 0)
513	    {
514	      return ret;
515	    }
516	
517	  /* §2.3 step 7: DAC digital path.  Gain, HPF bypass, clk invert. */
518	
519	  flags = spin_lock_irqsave(&g_bk7258_aud_lock);
520	  v = getreg32(BK7258_AUD_DAC_CONFIG0);
521	  v &= ~(AUD_DAC_CFG0_GAIN_MASK | AUD_DAC_CFG0_CLK_INVERT
522	         | AUD_DAC_CFG0_HPF1_BYPASS | AUD_DAC_CFG0_HPF2_BYPASS);
523	  v |= ((uint32_t)(cfg->gain & 0x3Fu) << AUD_DAC_CFG0_GAIN_SHIFT);
524	  v |= AUD_DAC_CFG0_HPF1_BYPASS | AUD_DAC_CFG0_HPF2_BYPASS;
525	  putreg32(v, BK7258_AUD_DAC_CONFIG0);
526	  spin_unlock_irqrestore(&g_bk7258_aud_lock, flags);
527	
528	  /* §2.4: FIFO read threshold.  With threshold=0 the audio block only
529	   * asserts a DMA request when the FIFO is completely empty; on a 32-word
530	   * FIFO that is one request per 32 samples, and combined with any DMA
531	   * arbitration latency the FIFO under-runs and stops requesting.  AVDK
532	   * uses 4 for BK7256; 8 leaves comfortable headroom on BK7258.
533	   */
534	
535	  {
536	    uint32_t fifo_cfg;
537	    fifo_cfg  = getreg32(BK7258_AUD_FIFO_CONFIG);
538	    fifo_cfg &= ~(AUD_FIFO_CFG_DACL_RD_TH_MASK
539	                  | AUD_FIFO_CFG_DACR_RD_TH_MASK);
540	    fifo_cfg |= (UINT32_C(8) << AUD_FIFO_CFG_DACL_RD_TH_SHIFT);
541	    fifo_cfg |= (UINT32_C(8) << AUD_FIFO_CFG_DACR_RD_TH_SHIFT);
542	    putreg32(fifo_cfg, BK7258_AUD_FIFO_CONFIG);
543	  }
544	
545	  /* §2.3 step 8: sample-rate divider. */
546	
547	  ret = bk7258_dac_set_sample_rate(cfg->samp_rate);
548	  if (ret < 0)
549	    {
550	      return ret;
551	    }
552	
553	  /* §2.3 step 9: previously we muted the DAC here.  Empirically the DAC
554	   * FIFO then never fully drains after start() unmutes; leaving the DAC
555	   * un-muted through configure() lets DMA replenish the FIFO immediately.
556	   */
557	
558	  g_bk7258_dac_configured = true;
559	  return OK;
560	}
561	
562	int bk7258_dac_set_sample_rate(uint32_t samp_rate)
563	{
564	  uint32_t sr_code;
565	  uint32_t fracmod = 0;
566	  bool     fracmod_manual = false;
567	  bool     apll_44k_family = false;
568	  uint32_t v;
569	  int ret;
570	
571	  switch (samp_rate)
572	    {
573	      case 8000:
574	        sr_code = AUD_SAMP_RATE_8K;
575	        break;
576	
577	      case 16000:
578	        sr_code = AUD_SAMP_RATE_16K;
579	        break;
580	
581	      case 44100:
582	        sr_code = AUD_SAMP_RATE_44_1K;
583	        apll_44k_family = true;
584	        break;
585	
586	      case 48000:
587	        sr_code = AUD_SAMP_RATE_48K;
588	        break;
589	
590	      case 11025:
591	        sr_code = AUD_SAMP_RATE_44_1K;
592	        fracmod = BK7258_AUD_CONST_DIV_44_1K << 2;
593	        fracmod_manual = true;
594	        apll_44k_family = true;
595	        break;
596	
597	      case 22050:
598	        sr_code = AUD_SAMP_RATE_44_1K;
599	        fracmod = BK7258_AUD_CONST_DIV_44_1K << 1;
600	        fracmod_manual = true;
601	        apll_44k_family = true;
602	        break;
603	
604	      case 12000:
605	        sr_code = AUD_SAMP_RATE_48K;
606	        fracmod = BK7258_AUD_CONST_DIV_48K << 2;
607	        fracmod_manual = true;
608	        break;
609	
610	      case 24000:
611	        sr_code = AUD_SAMP_RATE_48K;
612	        fracmod = BK7258_AUD_CONST_DIV_48K << 1;
613	        fracmod_manual = true;
614	        break;
615	
616	      case 32000:
617	        sr_code = AUD_SAMP_RATE_16K;
618	        fracmod = BK7258_AUD_CONST_DIV_16K >> 1;
619	        fracmod_manual = true;
620	        break;
621	
622	      default:
623	        auderr("BK7258: unsupported sample rate %lu\n",
624	               (unsigned long)samp_rate);
625	        return -EINVAL;
626	    }
627	
628	  /* On APLL, the 44.1k family requires a different cal value.  Re-run the
629	   * APLL bring-up transparently.
630	   */
631	
632	  if (g_bk7258_dac_use_apll)
633	    {
634	      ret = bk7258_apll_program(apll_44k_family
635	                                    ? BK7258_APLL_CAL_VAL_44_1K
636	                                    : BK7258_APLL_CAL_VAL_48K);
637	      if (ret < 0)
638	        {
639	          return ret;
640	        }
641	    }
642	
643	  /* Program fracmod first (upper half), then the samp_rate_DAC bits.  This
644	   * mirrors AVDK ordering and avoids a transient rate mismatch on the DAC
645	   * clock.
646	   */
647	
648	  v = getreg32(BK7258_AUD_EXTEND_CFG);
649	  v &= ~AUD_EXT_CFG_DAC_FRACMOD_MAN;
650	  if (fracmod_manual)
651	    {
652	      v |= AUD_EXT_CFG_DAC_FRACMOD_MAN;
653	    }
654	
655	  putreg32(v, BK7258_AUD_EXTEND_CFG);
656	
657	  if (fracmod_manual)
658	    {
659	      putreg32(fracmod, BK7258_AUD_DAC_FRACMOD);
660	    }
661	
662	  v = getreg32(BK7258_AUD_AUDIO_CONFIG);
663	  v &= ~AUD_AUDIO_CFG_SAMP_RATE_MASK;
664	  v |= (sr_code << AUD_AUDIO_CFG_SAMP_RATE_SHIFT)
665	       & AUD_AUDIO_CFG_SAMP_RATE_MASK;
666	  putreg32(v, BK7258_AUD_AUDIO_CONFIG);
